package reality_test

// Precision claims of the applied-formula packages: physics, fluids, em,
// acoustics and color.
//
// The cases live in testdata/stress/precision_applied.json, generated by
// tools/stressgolden/applied.py: each pairs a function with the precision its
// own docstring promises and an input where that promise is hardest to keep.
// This file registers the evaluators that call the functions, and lists in
// appliedKnownViolations the cases that measurably miss their claim, with the
// measured error. TestPrecisionClaims (precision_test.go) fails on any
// unlisted miss and on any listed case that starts to meet its claim, so the
// list can only shrink.
//
// Case ids read applied/<function>-<class>-<name>. The classes are typ
// (typical input), hard (hard input), extreme (an intermediate product
// overflows or underflows although the result is representable) and cond
// (ill-conditioned: any float64 evaluation of the formula loses this much).

import (
	"fmt"
	"math"
	"strings"

	"github.com/davly/reality/acoustics"
	"github.com/davly/reality/color"
	"github.com/davly/reality/em"
	"github.com/davly/reality/fluids"
	"github.com/davly/reality/physics"
)

// regF registers the evaluator of a function of float arguments. keys names
// the arguments in call order, separated by spaces; they are the parameter
// names in the case file.
func regF(name, keys string, f func(a []float64) float64) {
	ks := strings.Fields(keys)
	registerPrecisionEvaluator(name, func(c precisionCase) (float64, error) {
		a := make([]float64, len(ks))
		for i, k := range ks {
			a[i] = argF(c, k)
		}
		return f(a), nil
	})
}

// appliedList reads a resistor list from a case: an explicit array "r", or
// "count" copies of "value" (so a long list need not be written out).
func appliedList(c precisionCase) ([]float64, error) {
	if raw, ok := c.Args["r"].([]any); ok {
		out := make([]float64, len(raw))
		for i, v := range raw {
			f, ok := v.(float64)
			if !ok {
				return nil, fmt.Errorf("r[%d] is not a number", i)
			}
			out[i] = f
		}
		return out, nil
	}
	out := make([]float64, argI(c, "count"))
	for i := range out {
		out[i] = argF(c, "value")
	}
	return out, nil
}

// heatTruncation returns the truncation error per unit time of one step of
// physics.HeatEquation1DStep on the discrete sine mode sin(pi x_i), x_i =
// i/(n-1), measured at the midpoint node. The mode is an exact eigenvector of
// the three-point stencil, so the step multiplies it by one factor g, and the
// exact heat equation multiplies it by exp(-alpha pi^2 dt): the difference,
// divided by dt, is the truncation error per unit time. Its expansion is
// alpha pi^4 dx^2 / 12 - alpha^2 pi^4 dt / 2 + ..., so it is first order in
// dt and second order in dx exactly when the documented orders hold.
func heatTruncation(n int, alpha, dt float64) float64 {
	dx := 1 / float64(n-1)
	u := make([]float64, n)
	out := make([]float64, n)
	for i := 1; i < n-1; i++ {
		u[i] = math.Sin(math.Pi * float64(i) * dx)
	}
	physics.HeatEquation1DStep(u, dt, dx, alpha, out)
	mid := n / 2
	return (out[mid]/u[mid] - math.Exp(-alpha*math.Pi*math.Pi*dt)) / dt
}

