	registerPrecisionEvaluator("acoustics.ResonantFrequency", func(c precisionCase) (float64, error) {
		return acoustics.ResonantFrequency(argF(c, "L"), argI(c, "n"), argF(c, "c")), nil
	})
	regF("acoustics.WaveLength", "f c", func(a []float64) float64 { return acoustics.WaveLength(a[0], a[1]) })
	regF("acoustics.AWeighting", "f", func(a []float64) float64 { return acoustics.AWeighting(a[0]) })

	// em
