	regF("em.ElectricField", "q r", func(a []float64) float64 { return em.ElectricField(a[0], a[1]) })
	regF("em.OhmsLaw", "V R", func(a []float64) float64 { return em.OhmsLaw(a[0], a[1]) })
	regF("em.PowerElectric", "V I", func(a []float64) float64 { return em.PowerElectric(a[0], a[1]) })
	registerPrecisionEvaluator("em.ResistorsInSeries", func(c precisionCase) (float64, error) {
		r, err := appliedList(c)
		return em.ResistorsInSeries(r), err
	})
	registerPrecisionEvaluator("em.ResistorsInParallel", func(c precisionCase) (float64, error) {
		r, err := appliedList(c)
		return em.ResistorsInParallel(r), err
	})
	regF("em.CapacitorEnergy", "C V", func(a []float64) float64 { return em.CapacitorEnergy(a[0], a[1]) })
	regF("em.InductorEnergy", "L I", func(a []float64) float64 { return em.InductorEnergy(a[0], a[1]) })
	regF("em.RCTimeConstant", "R C", func(a []float64) float64 { return em.RCTimeConstant(a[0], a[1]) })
	regF("em.ResonantFrequencyLC", "L C", func(a []float64) float64 { return em.ResonantFrequencyLC(a[0], a[1]) })

	// fluids
	regF("fluids.ReynoldsNumber", "rho v L mu", func(a []float64) float64 { return fluids.ReynoldsNumber(a[0], a[1], a[2], a[3]) })
	regF("fluids.BernoulliPressure", "rho v1 p1 h1 v2 h2 g", func(a []float64) float64 {
		return fluids.BernoulliPressure(a[0], a[1], a[2], a[3], a[4], a[5], a[6])
	})
	regF("fluids.PipeFlowFriction", "Re roughness diameter", func(a []float64) float64 { return fluids.PipeFlowFriction(a[0], a[1], a[2]) })
	regF("fluids.DarcyWeisbach", "f L D rho v", func(a []float64) float64 { return fluids.DarcyWeisbach(a[0], a[1], a[2], a[3], a[4]) })
	regF("fluids.DragForce", "Cd rho v A", func(a []float64) float64 { return fluids.DragForce(a[0], a[1], a[2], a[3]) })
	regF("fluids.LiftForce", "Cl rho v A", func(a []float64) float64 { return fluids.LiftForce(a[0], a[1], a[2], a[3]) })
	regF("fluids.TerminalVelocity", "m g Cd rho A", func(a []float64) float64 { return fluids.TerminalVelocity(a[0], a[1], a[2], a[3], a[4]) })
	regF("fluids.StokesLaw", "mu r v", func(a []float64) float64 { return fluids.StokesLaw(a[0], a[1], a[2]) })
	regF("fluids.MassFlowRate", "rho v A", func(a []float64) float64 { return fluids.MassFlowRate(a[0], a[1], a[2]) })
	regF("fluids.VolumetricFlowRate", "v A", func(a []float64) float64 { return fluids.VolumetricFlowRate(a[0], a[1]) })

	// physics: mechanics
	regF("physics.NewtonSecondLaw", "F m", func(a []float64) float64 { return physics.NewtonSecondLaw(a[0], a[1]) })
	regF("physics.ProjectilePosition.x", "v0 theta t g", func(a []float64) float64 {
		x, _ := physics.ProjectilePosition(a[0], a[1], a[2], a[3])
		return x
	})
	regF("physics.ProjectilePosition.y", "v0 theta t g", func(a []float64) float64 {
		_, y := physics.ProjectilePosition(a[0], a[1], a[2], a[3])
		return y
	})
	regF("physics.GravitationalForce", "m1 m2 r", func(a []float64) float64 { return physics.GravitationalForce(a[0], a[1], a[2]) })
	regF("physics.OrbitalVelocity", "M r", func(a []float64) float64 { return physics.OrbitalVelocity(a[0], a[1]) })
	regF("physics.SpringForce", "k x c v", func(a []float64) float64 { return physics.SpringForce(a[0], a[1], a[2], a[3]) })
	regF("physics.ElasticCollision.v1f", "m1 v1 m2 v2", func(a []float64) float64 {
		v1f, _ := physics.ElasticCollision(a[0], a[1], a[2], a[3])
		return v1f
	})
	regF("physics.ElasticCollision.v2f", "m1 v1 m2 v2", func(a []float64) float64 {
		_, v2f := physics.ElasticCollision(a[0], a[1], a[2], a[3])
		return v2f
	})
	regF("physics.Pendulum", "theta L g damping", func(a []float64) float64 { return physics.Pendulum(a[0], a[1], a[2], a[3]) })
	regF("physics.KineticEnergy", "m v", func(a []float64) float64 { return physics.KineticEnergy(a[0], a[1]) })
	regF("physics.PotentialEnergy", "m g h", func(a []float64) float64 { return physics.PotentialEnergy(a[0], a[1], a[2]) })

	// physics: materials
	regF("physics.HookesLaw", "E epsilon", func(a []float64) float64 { return physics.HookesLaw(a[0], a[1]) })
	regF("physics.VonMisesStress", "s1 s2 s3", func(a []float64) float64 { return physics.VonMisesStress(a[0], a[1], a[2]) })
	regF("physics.TrescaStress", "s1 s2 s3", func(a []float64) float64 { return physics.TrescaStress(a[0], a[1], a[2]) })
	regF("physics.StressIntensityFactor", "sigma a Y", func(a []float64) float64 { return physics.StressIntensityFactor(a[0], a[1], a[2]) })
	regF("physics.GriffithCriterion", "E gamma a", func(a []float64) float64 { return physics.GriffithCriterion(a[0], a[1], a[2]) })
	regF("physics.ParisLaw", "C m deltaK", func(a []float64) float64 { return physics.ParisLaw(a[0], a[1], a[2]) })
	registerPrecisionEvaluator("physics.CoffinManson", func(c precisionCase) (float64, error) {
		return physics.CoffinManson(argF(c, "epsilonF"), argF(c, "c"), argI(c, "Nf")), nil
	})
	regF("physics.CreepArrhenius", "A Q R T sigma n", func(a []float64) float64 {
		return physics.CreepArrhenius(a[0], a[1], a[2], a[3], a[4], a[5])
	})
	regF("physics.CompositeMixture", "Vf Ef Em", func(a []float64) float64 { return physics.CompositeMixture(a[0], a[1], a[2]) })
	regF("physics.EulerBuckling", "E I L K", func(a []float64) float64 { return physics.EulerBuckling(a[0], a[1], a[2], a[3]) })
	regF("physics.BeamDeflection", "P L E I", func(a []float64) float64 { return physics.BeamDeflection(a[0], a[1], a[2], a[3]) })

	// physics: thermodynamics
	regF("physics.IdealGas", "n T V", func(a []float64) float64 { return physics.IdealGas(a[0], a[1], a[2]) })
	regF("physics.StefanBoltzmann", "T A emissivity", func(a []float64) float64 { return physics.StefanBoltzmann(a[0], a[1], a[2]) })
	regF("physics.CarnotEfficiency", "Th Tc", func(a []float64) float64 { return physics.CarnotEfficiency(a[0], a[1]) })
	regF("physics.FourierHeatConduction", "k A dTdx", func(a []float64) float64 { return physics.FourierHeatConduction(a[0], a[1], a[2]) })
	regF("physics.NewtonCooling", "h A Ts Tinf", func(a []float64) float64 { return physics.NewtonCooling(a[0], a[1], a[2], a[3]) })
	regF("physics.ThermalExpansion", "L0 alpha deltaT", func(a []float64) float64 { return physics.ThermalExpansion(a[0], a[1], a[2]) })
	registerPrecisionEvaluator("physics.HeatEquation1DStep.order_dt", func(c precisionCase) (float64, error) {
		n, alpha, dt := argI(c, "n"), argF(c, "alpha"), argF(c, "dt")
		t1, t2, t3 := heatTruncation(n, alpha, dt), heatTruncation(n, alpha, dt/2), heatTruncation(n, alpha, dt/4)
		return math.Log2((t1 - t2) / (t2 - t3)), nil
	})
	registerPrecisionEvaluator("physics.HeatEquation1DStep.order_dx", func(c precisionCase) (float64, error) {
		n, alpha, dt := argI(c, "n"), argF(c, "alpha"), argF(c, "dt")
		// Richardson extrapolation in dt removes the O(dt) term of the truncation error.
		coarse := 2*heatTruncation(n, alpha, dt/2) - heatTruncation(n, alpha, dt)
		fine := 2*heatTruncation(2*n-1, alpha, dt/2) - heatTruncation(2*n-1, alpha, dt)
		return math.Log2(coarse / fine), nil
	})

	// physics: optics
	regF("physics.SnellRefraction", "n1 n2 thetaI", func(a []float64) float64 { return physics.SnellRefraction(a[0], a[1], a[2]) })
